#include "datastore.h"
#include "window.h"
#include "journalpath.h"
#include <QtWidgets>
#include <QSqlQuery>
#include <QSqlError>
#include <QSqlRecord>
namespace {
void require(bool ok,QString error){if(!ok)throw std::runtime_error(error.toStdString());}
QString checkedDatabase(QString directory){QString name="verify-"+QUuid::createUuid().toString();QString result;{auto db=QSqlDatabase::addDatabase("QSQLITE",name);db.setDatabaseName(QDir(directory).filePath("pocsag.db"));db.setConnectOptions("QSQLITE_OPEN_READONLY");if(!db.open())result=db.lastError().text();else{QSqlQuery q(db);if(!q.exec("PRAGMA integrity_check")||!q.next()||q.value(0).toString()!="ok")result="Échec du contrôle d’intégrité SQLite";q.finish();QSqlQuery shape(db);if(result.isEmpty()&&(!shape.exec("SELECT count(*) FROM messages")||!shape.next()))result="Base POCSAG absente ou invalide";shape.finish();db.close();}}QSqlDatabase::removeDatabase(name);return result;}
void copyTree(QString source,QString target){require(QDir().mkpath(target),"Création impossible : "+target);for(const auto& item:QDir(source).entryInfoList(QDir::Files|QDir::Dirs|QDir::Hidden|QDir::NoDotAndDotDot)){auto name=item.fileName();if(name=="pocsag.db"||name=="pocsag.db-wal"||name=="pocsag.db-shm"||name.endsWith(".lock"))continue;require(!item.isSymLink(),"Lien symbolique non copié : "+item.filePath());auto to=QDir(target).filePath(name);if(item.isDir())copyTree(item.filePath(),to);else{require(QFile::copy(item.filePath(),to),"Copie impossible : "+item.filePath());QFile a(item.filePath()),b(to);require(a.open(QIODevice::ReadOnly)&&b.open(QIODevice::ReadOnly),"Contrôle de copie impossible");QCryptographicHash ha(QCryptographicHash::Sha256),hb(QCryptographicHash::Sha256);require(ha.addData(&a)&&hb.addData(&b)&&ha.result()==hb.result(),"Copie différente : "+to);}}}
bool locator(QString directory,QString previous,QString filename,QString* error){QSaveFile f(filename);auto data=QJsonDocument(QJsonObject{{"directory",directory},{"previous",previous}}).toJson();if(!QDir().mkpath(QFileInfo(filename).absolutePath())||!f.open(QIODevice::WriteOnly)||f.write(data)!=data.size()||!f.commit()){if(error)*error="Localisation des données non sauvegardée : "+f.errorString();return false;}return true;}
}
QString resolveDataStore(QString original){QFile file(QDir(original).filePath("storage-location.json"));if(!file.exists())return original;require(file.open(QIODevice::ReadOnly),"Localisation des données illisible : "+file.fileName());QJsonParseError error;auto doc=QJsonDocument::fromJson(file.readAll(),&error);require(error.error==QJsonParseError::NoError&&doc.isObject(),"Localisation des données invalide ; aucun repli automatique.");auto path=doc.object()["directory"].toString();require(absoluteTxtPath(normalizedTxtPath(path))&&QFileInfo(QDir(path).filePath("pocsag.db")).isFile(),"Données actives inaccessibles : "+path+". Rétablissez ce disque ou choisissez explicitement --data-directory. Aucun repli automatique.");return path;}
bool activateDataStore(QString directory,QString previous,QString filename,QString* error){auto reason=checkedDatabase(directory);if(!reason.isEmpty()){if(error)*error=reason;return false;}return locator(directory,previous,filename,error);}
StoreMigration copyDataStore(QString source,QString destination,QString filename){StoreMigration result;try{require(absoluteTxtPath(normalizedTxtPath(destination)),"Dossier cible absolu requis");require(QFileInfo(QDir(source).filePath("pocsag.db")).isFile(),"Base source absente");source=QDir::cleanPath(QFileInfo(source).absoluteFilePath());destination=QDir::cleanPath(QFileInfo(destination).absoluteFilePath());auto src=txtPathKey(source),dst=txtPathKey(destination);require(absoluteTxtPath(normalizedTxtPath(destination)),"Dossier cible absolu requis");require(src!=dst&&!dst.startsWith(src+'/')&&!src.startsWith(dst+'/'),"Choisissez un dossier extérieur au dossier actuel");require(!QFileInfo(destination).isSymLink(),"Le dossier cible ne doit pas être un lien");require(!QFileInfo::exists(destination)||QDir(destination).entryList(QDir::AllEntries|QDir::Hidden|QDir::NoDotAndDotDot).isEmpty(),"Le dossier cible doit être nouveau ou vide ; aucun fichier existant ne sera remplacé");
 QString token=QUuid::createUuid().toString(QUuid::WithoutBraces);auto parent=QFileInfo(destination).absolutePath();require(QDir().mkpath(parent),"Dossier cible inaccessible");result.backup=QDir(parent).filePath("POCSAG-sauvegarde-"+QDateTime::currentDateTimeUtc().toString("yyyyMMdd-HHmmss")+"-"+token);result.staging=QDir(parent).filePath(".pocsag-copie-"+token);require(QDir().mkpath(result.backup),"Sauvegarde inaccessible");
 QString connection="migration-"+token;QString dbError;{auto db=QSqlDatabase::addDatabase("QSQLITE",connection);db.setDatabaseName(QDir(source).filePath("pocsag.db"));if(!db.open())dbError=db.lastError().text();else{auto exec=[&](QString sql){QSqlQuery q(db);if(!q.exec(sql)&&dbError.isEmpty())dbError=q.lastError().text();q.finish();};exec("PRAGMA busy_timeout=1000");exec("PRAGMA locking_mode=EXCLUSIVE");exec("BEGIN EXCLUSIVE");exec("COMMIT");if(dbError.isEmpty()){auto out=QDir(result.backup).filePath("pocsag.db");out.replace("'","''");exec("VACUUM INTO '"+out+"'");}db.close();}}QSqlDatabase::removeDatabase(connection);require(dbError.isEmpty(),"Base occupée ou sauvegarde impossible : "+dbError);require(checkedDatabase(result.backup).isEmpty(),"Sauvegarde SQLite invalide");copyTree(source,result.backup);copyTree(result.backup,result.staging);require(QFile::copy(QDir(result.backup).filePath("pocsag.db"),QDir(result.staging).filePath("pocsag.db")),"Copie SQLite impossible");{QFile a(QDir(result.backup).filePath("pocsag.db")),b(QDir(result.staging).filePath("pocsag.db"));require(a.open(QIODevice::ReadOnly)&&b.open(QIODevice::ReadOnly),"Copie SQLite illisible");QCryptographicHash ha(QCryptographicHash::Sha256),hb(QCryptographicHash::Sha256);require(ha.addData(&a)&&hb.addData(&b)&&ha.result()==hb.result(),"Empreintes SQLite différentes");}require(checkedDatabase(result.staging).isEmpty(),"Base copiée invalide");if(QDir(destination).exists())require(QDir().rmdir(destination),"Dossier cible devenu non vide ; copie non activée");require(QDir().rename(result.staging,destination),"Activation du dossier copié impossible");QString error;require(locator(destination,source,filename,&error),error);result.ok=true;
 }catch(const std::exception& e){result.error=QString::fromUtf8(e.what())+"\nLes données originales et toute sauvegarde créée sont conservées.";}return result;}
void Window::storageOptions(){QDialog dialog(this);dialog.setWindowTitle("Emplacement des données actives — migration explicite");auto form=new QFormLayout(&dialog);auto source=QFileInfo(db_.databaseName()).absolutePath();auto current=new QLabel(QDir::toNativeSeparators(source));current->setTextInteractionFlags(Qt::TextSelectableByMouse);form->addRow("Dossier actuellement utilisé",current);auto diagnose=new QPushButton("Diagnostic de la connexion SQLite (lecture seule)…");diagnose->setObjectName("sqliteConnectionDiagnostic");form->addRow(diagnose);connect(diagnose,&QPushButton::clicked,&dialog,[this,&dialog]{QDialog report(&dialog);report.setWindowTitle("Connexion SQLite réellement ouverte — lecture seule");report.resize(850,600);QVBoxLayout layout(&report);QPlainTextEdit output;output.setObjectName("sqliteConnectionReport");output.setReadOnly(true);QLineEdit event;event.setObjectName("sqliteEventId");event.setPlaceholderText("UUID de l'événement à rechercher");QPushButton search("Rechercher l'événement en lecture seule");search.setObjectName("sqliteEventSearch");layout.addWidget(&output);layout.addWidget(&event);layout.addWidget(&search);auto inspect=[&]{QString text="Processus : "+QString::number(QCoreApplication::applicationPid())+"\nExécutable : "+QCoreApplication::applicationFilePath()+"\nPilote : "+db_.driverName()+"\nConnexion : "+db_.connectionName()+"\nBase déclarée : "+db_.databaseName()+"\n";for(auto suffix:{QString{},QString("-wal"),QString("-shm")}){QFileInfo info(db_.databaseName()+suffix);text+=info.absoluteFilePath()+" : "+(info.exists()?QString::number(info.size())+" octets ; modifié "+info.lastModified().toString(Qt::ISODateWithMs):QString("absent"))+"\n";}for(auto statement:{QString("PRAGMA database_list"),QString("PRAGMA user_version"),QString("SELECT sqlite_version(),count(*) FROM messages")}){QSqlQuery q(db_);text+="\n"+statement+"\n";if(q.exec(statement)){while(q.next()){for(int col=0;col<q.record().count();++col)text+=q.value(col).toString()+" | ";text+="\n";}}else text+="ERREUR : "+q.lastError().text()+"\n";q.finish();}if(!event.text().trimmed().isEmpty()){QSqlQuery q(db_);q.prepare("SELECT timestamp,type,length(text),length(raw_bits),length(raw_codewords),decode_status,interpretation_policy,capture_origin FROM messages WHERE event_uid=?");q.addBindValue(event.text().trimmed());text+="\nÉvénement : "+event.text().trimmed()+"\n";if(!q.exec())text+="ERREUR : "+q.lastError().text();else if(!q.next())text+="Événement absent de cette connexion.";else for(int col=0;col<q.record().count();++col)text+=q.record().fieldName(col)+" : "+q.value(col).toString()+"\n";q.finish();}output.setPlainText(text);};connect(&search,&QPushButton::clicked,&report,inspect);inspect();report.exec();});auto target=new QLineEdit;target->setPlaceholderText("Dossier nouveau ou vide sur un disque disposant d’espace");form->addRow("Nouveau dossier",target);auto browse=new QPushButton("Parcourir…");form->addRow(browse);connect(browse,&QPushButton::clicked,&dialog,[&]{auto p=QFileDialog::getExistingDirectory(&dialog,"Destination de la copie vérifiée");if(!p.isEmpty())target->setText(p);});auto note=new QLabel("La réception sera arrêtée. Une sauvegarde puis une copie vérifiée seront créées sur le disque cible. Le dossier original reste intact. L’application se ferme après activation ; relancez-la. Aucun TXT externe n’est déplacé.");note->setWordWrap(true);form->addRow(note);auto migrate=new QPushButton("Sauvegarder et copier les données…");form->addRow(migrate);auto restore=new QPushButton("Réactiver le dossier précédent…");form->addRow(restore);auto close=new QDialogButtonBox(QDialogButtonBox::Close);form->addRow(close);connect(close,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);
 auto stop=[&]{receiveWanted_=false;stopReceivers();QCoreApplication::sendPostedEvents(this,QEvent::MetaCall);pumpMessages();storePreferences();saveOptions();ingestionTimer_->stop();refreshTimer_->stop();journalWorker_->shutdown();if(pagerWorker_)pagerWorker_->shutdown();speech_.stopSpeaking();allView_->setUpdatesEnabled(false);savedView_->setUpdatesEnabled(false);db_.close();};auto resume=[&]{if(!db_.open())technical("Réouverture de la base impossible : "+db_.lastError().text());else sql("PRAGMA busy_timeout=50");journalWorker_=std::make_unique<JournalWorker>(db_.databaseName());connect(journalWorker_.get(),&JournalWorker::problem,this,&Window::technical);journalWorker_->start();startPagerWorker();ingestionTimer_->start(200);allView_->setUpdatesEnabled(true);savedView_->setUpdatesEnabled(true);refresh();};
 connect(migrate,&QPushButton::clicked,&dialog,[&]{auto destination=normalizedTxtPath(target->text());if(!absoluteTxtPath(destination)){QMessageBox::warning(&dialog,"Dossier","Chemin absolu requis.");return;}if(QMessageBox::question(&dialog,"Copie explicite des données","Arrêter la réception, sauvegarder puis copier la base, les préférences et les files vers :\n"+destination+"\nFermez les autres versions avant de continuer.")!=QMessageBox::Yes)return;stop();auto result=copyDataStore(source,destination,bootstrapFile_);if(!result.ok){resume();QMessageBox::warning(&dialog,"Migration non activée",result.error);return;}QMessageBox::information(&dialog,"Copie vérifiée","Nouveau dossier : "+destination+"\nSauvegarde : "+result.backup+"\nRelancez l’application. Le dossier original est conservé.");dialog.accept();QCoreApplication::quit();});connect(restore,&QPushButton::clicked,&dialog,[&]{QFile file(bootstrapFile_);if(!file.open(QIODevice::ReadOnly))return;auto previous=QJsonDocument::fromJson(file.readAll()).object()["previous"].toString();if(previous.isEmpty()){QMessageBox::information(&dialog,"Retour","Aucun dossier précédent enregistré.");return;}if(QMessageBox::question(&dialog,"Réactiver sans fusion","Réactiver :\n"+previous+"\nLe dossier actuel reste intact. Aucune fusion ou suppression n’est effectuée.")!=QMessageBox::Yes)return;stop();QString error;if(!activateDataStore(previous,source,bootstrapFile_,&error)){resume();QMessageBox::warning(&dialog,"Retour non activé",error);return;}dialog.accept();QCoreApplication::quit();});dialog.exec();}
